+    var(--color-cobalt) 4%
+  );
+}
+.flow-card.is-hovered {
+  transform: translateY(-1px);
+  box-shadow:
+    0 1px 0 var(--color-paper-3),
+    0 14px 28px -16px rgb(0 0 0 / 0.5);
+  z-index: 3;
+}
+@keyframes flow-slip-in {
+  from {
+    opacity: 0;
+    transform: translateX(10px);
+  }
+}
+.flow-column--archive .flow-card {
+  animation-name: flow-slip-in-left;
+}
+@keyframes flow-slip-in-left {
+  from {
+    opacity: 0;
+    transform: translateX(-10px);
+  }
+}
+.flow-card__head {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 0.5rem;
+}
+.flow-card__kicker {
+  font: 0.62rem/1.2 var(--font-typewriter);
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: var(--flow-accent, var(--color-ink-muted));
+}
+.flow-card__close {
+  border: 0;
+  background: none;
+  color: var(--color-ink-muted);
+  font-size: 0.7rem;
+  cursor: pointer;
+  opacity: 0;
+  transition: opacity 120ms ease;
+}
+.flow-card:hover .flow-card__close,
+.flow-card:focus-within .flow-card__close {
+  opacity: 1;
+}
+.flow-card__close:hover {
+  color: var(--color-vermilion);
+}
+.flow-card__body {
+  display: flex;
+  flex-direction: column;
+  gap: 0.25rem;
+  padding: 0;
+  border: 0;
+  background: none;
+  color: inherit;
+  font: inherit;
+  text-align: left;
+  cursor: pointer;
+}
+.flow-card__title {
+  font-family: var(--font-display);
+  font-size: 0.86rem;
+  font-weight: 700;
+  line-height: 1.3;
+}
+.flow-card__text {
+  color: var(--color-ink-light);
+}
+/* An echo reads as a carbon copy of the writer's own page. */
+.flow-card__carbon {
+  font-family: var(--font-typewriter);
+  font-size: 0.72rem;
+  line-height: 1.55;
+  color: color-mix(in srgb, var(--color-cobalt) 70%, var(--color-ink));
+  opacity: 0.9;
+}
+.flow-card__reply {
+  margin: 0;
+  padding: 0.45rem 0 0 0.6rem;
+  border-left: 1px solid var(--flow-accent, var(--color-paper-3));
+  color: var(--color-ink);
+  font-style: italic;
+}
+.flow-card__reply-by {
+  display: block;
+  font: normal 0.6rem/1.3 var(--font-typewriter);
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: var(--color-ink-muted);
+}
+.flow-card__reply.is-streaming::after {
+  content: "▍";
+  margin-left: 1px;
+  color: var(--flow-accent, var(--color-ink));
+  animation: flow-caret 1s steps(2) infinite;
+}
+@keyframes flow-caret {
+  50% {
+    opacity: 0;
+  }
+}
+.flow-card__foot {
+  display: flex;
+  justify-content: space-between;
+  gap: 0.5rem;
+  font: 0.62rem/1.3 var(--font-typewriter);
+  color: var(--color-ink-muted);
+}
+.flow-card__notice {
+  margin: 0;
+  font-size: 0.72rem;
+  color: var(--color-ink-muted);
+}
+.flow-link {
+  border: 0;
+  padding: 0;
+  background: none;
+  color: var(--color-cobalt);
+  font: 0.7rem var(--font-typewriter);
+  text-decoration: underline;
+  text-underline-offset: 2px;
+  cursor: pointer;
+}
+.flow-link:disabled {
+  opacity: 0.5;
+  cursor: default;
+}
