+  width: 100%;
+  padding: 0.4rem 0.5rem;
+  border: 1px solid var(--color-paper-3);
+  background: var(--color-editor-bg);
+  color: var(--color-ink);
+  font: 0.8rem/1.45 var(--font-typewriter);
+  resize: vertical;
+}
+.flow-amend__input:focus {
+  outline: 1px solid var(--color-vermilion);
+}
