+  display: flex;
+  gap: 0.7rem;
+  color: inherit;
+  text-decoration: none;
+}
+.flow-work__sleeve {
+  position: relative;
+  flex-shrink: 0;
+}
+.flow-work__sleeve img,
+.flow-work__blank {
+  position: relative;
+  z-index: 1;
+  display: block;
+  width: 72px;
+  object-fit: cover;
+  background: var(--color-paper-2);
+  box-shadow:
+    1px 1px 0 var(--color-paper-3),
+    3px 5px 10px -6px rgb(0 0 0 / 0.5);
+}
+.flow-work--book .flow-work__sleeve img,
+.flow-work--book .flow-work__blank {
+  height: 108px;
+  border-radius: 1px 3px 3px 1px;
+}
+.flow-work--album .flow-work__sleeve img,
+.flow-work--song .flow-work__sleeve img,
+.flow-work--album .flow-work__blank,
+.flow-work--song .flow-work__blank {
+  height: 72px;
+}
+.flow-work__blank {
+  display: grid;
+  place-items: center;
+  font: 700 1.6rem var(--font-display);
+  color: var(--color-ink-muted);
+}
+.flow-work__disc {
+  position: absolute;
+  top: 4px;
+  left: 18px;
+  width: 64px;
+  height: 64px;
+  border-radius: 50%;
+  background:
+    radial-gradient(
+      circle,
+      var(--color-mustard) 0 14%,
+      #111 15% 17%,
+      transparent 18%
+    ),
+    repeating-radial-gradient(circle, #1a1a1a 0 1px, #262626 1px 3px);
+  transition: transform 240ms ease;
+}
+.flow-work:hover .flow-work__disc {
+  transform: translateX(14px) rotate(40deg);
+}
+.flow-work__text {
+  display: flex;
+  flex-direction: column;
+  gap: 0.15rem;
+  min-width: 0;
+}
+.flow-work__medium {
+  font: 0.6rem var(--font-typewriter);
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+  color: var(--color-ink-muted);
+}
+.flow-work__text strong {
+  font-family: var(--font-display);
+  line-height: 1.25;
+}
+.flow-work__text span:last-child {
+  font-size: 0.76rem;
+  color: var(--color-ink-light);
+}
+.flow-waiting {
+  position: absolute;
+  left: 0;
+  padding: 0.2rem 0.55rem;
+  border: 1px dashed var(--color-paper-3);
+  border-radius: 999px;
+  background: var(--color-paper);
+  color: var(--color-ink-muted);
+  font: 0.64rem var(--font-typewriter);
+  letter-spacing: 0.05em;
+  cursor: pointer;
+  transition: top 220ms ease;
+}
+.flow-waiting:hover {
+  color: var(--color-ink);
+  border-style: solid;
+}
+.flow-dock {
+  position: fixed;
+  right: 16px;
+  bottom: 16px;
+  z-index: var(--z-dropdown);
+  width: min(300px, calc(100vw - 32px));
+  pointer-events: auto;
+}
+.flow-dock .flow-card {
+  position: relative;
+}
+.flow-dock__more {
+  margin: 0.3rem 0 0;
+  font: 0.62rem var(--font-typewriter);
+  color: var(--color-ink-muted);
+  text-align: right;
+}
+
+/* The chrome eases out as a run builds and stays out in flow. The page
+   itself never moves. */
+[data-flow="settling"] .editor-workspace-main > header,
+[data-flow="settling"] .twyne-toolbar,
+[data-flow="settling"] .in-flow-rails,
+[data-flow="settling"] .flow-surface {
+  opacity: 0.4;
+  transition: opacity 1.2s ease;
+}
+[data-flow="flow"] .flow-surface,
+[data-flow="flow"] .in-flow-rails {
+  opacity: 0;
+  pointer-events: none;
+  transition: opacity 0.8s ease;
+}
+/* In flow the masthead, the review line and the docked panels recede but
+   keep their size, so the page does not move. Reaching for them (hover,
+   keyboard focus) brings them straight back. */
+[data-flow="flow"] .editor-workspace-main > header,
+[data-flow="flow"] .twyne-toolbar,
+[data-flow="flow"] .live-review-status,
+[data-flow="flow"] .editor-workspace-shell > aside {
+  opacity: 0.12;
+  transition: opacity 1.2s ease;
+}
+[data-flow="settling"] .editor-workspace-main > header:hover,
+[data-flow="settling"] .twyne-toolbar:hover,
+[data-flow="flow"] .editor-workspace-main > header:hover,
+[data-flow="flow"] .editor-workspace-main > header:focus-within,
+[data-flow="flow"] .twyne-toolbar:hover,
+[data-flow="flow"] .twyne-toolbar:focus-within,
+[data-flow="flow"] .live-review-status:hover,
+[data-flow="flow"] .editor-workspace-shell > aside:hover,
+[data-flow="flow"] .editor-workspace-shell > aside:focus-within {
+  opacity: 1;
+  transition-duration: 0.2s;
+}
+[data-flow="stuck"] .flow-card {
+  animation: flow-slip-in 360ms ease-out;
+}
+/* A proposed rewrite: the struck original above, the new wording below. */
+.suggestion-card__struck {
+  color: var(--color-ink-muted);
+  font: 0.85rem/1.5 var(--font-serif);
+  text-decoration: line-through;
+  text-decoration-color: var(--comment-color);
+}
+.suggestion-card__replacement {
+  color: var(--color-ink);
+  font: 0.95rem/1.5 var(--font-serif);
+}
+.suggestion-card__why {
+  color: var(--color-ink-light);
+  font: italic 0.78rem/1.45 var(--font-serif);
+}
+
+/* A persona note wears the shared comment-card layout; the older
+   stand-alone note card's padding and paper would frame it as a card
+   inside a card. */
+.persona-note-card.manuscript-comment-card,
+.suggestion-card.manuscript-comment-card {
+  padding: 0;
+  background: var(--color-paper);
+  border-color: var(--comment-color);
+}
+
+/* A conversation opened in the margin takes its card's place: the card
+   steps aside and the thread unfolds from the same top edge, in the same
+   accent, so it reads as the card opening rather than a second card. */
+.flow-card.is-unfolded {
+  visibility: hidden;
+  pointer-events: none;
+}
+.manuscript-comment-card.is-in-margin {
+  border-width: 1px;
+  border-color: var(--color-paper-3);
+  border-top: 3px solid var(--comment-color);
+  border-radius: 2px;
+  box-shadow:
+    0 1px 0 var(--color-paper-3),
+    0 18px 32px -18px rgb(0 0 0 / 0.45);
+  transform-origin: top center;
+  animation: margin-unfold 180ms ease-out;
+  transition:
+    top 160ms ease-out,
+    left 160ms ease-out;
+}
+@keyframes margin-unfold {
+  from {
+    opacity: 0.4;
+    transform: scaleY(0.94);
+  }
+  to {
+    opacity: 1;
+    transform: none;
+  }
+}
+@media (prefers-reduced-motion: reduce) {
+  .flow-card,
+  .flow-overlay__line,
+  .flow-work__disc,
+  .manuscript-comment-card.is-in-margin,
+  [data-flow] .editor-workspace-main > header {
+    animation: none;
+    transition: none;
+  }
+  .flow-overlay__line {
+    stroke-dashoffset: 0;
+  }
+}
+@media print {
+  .flow-surface,
+  .flow-dock {
+    display: none !important;
+  }
+}
+
+/* A narrow desk has one foreground surface at a time. Keep ambient cards
+   quiet while the writer uses a conversation, selection action or tool. */
+body:has(
+    .manuscript-comment-card,
+    .in-flow-rail,
+    .in-flow-popover,
+    .twyne-quick-review-card,
+    .selection-actions,
+    [role="dialog"]
+  )
+  .flow-dock {
+  display: none;
+}

